export function pavilionSelection(event,chosen=[]){return [...new Set(Array.isArray(chosen)?chosen:[])].filter(id=>event.products.includes(id)).slice(0,2);}
export function togglePavilionPick(event,chosen,id){const next=pavilionSelection(event,chosen);if(!event.products.includes(id))return next;return next.includes(id)?next.filter(v=>v!==id):next.length<2?[...next,id]:next;}
export function pavilionCoupon(s,event){const claimed=s.popupStamps.some(p=>p.day===s.day),active=s.coupon?.day===s.day&&s.coupon.store===event.store;return {claimed,active};}
export function pavilionGuideHTML(s,event,chosen,{E,esc,picture}){
 const ids=pavilionSelection(event,chosen),selected=ids.map(E.byId),stockist=E.storeById(event.store),coupon=pavilionCoupon(s,event);
 return `<div class="modal-body pavilion-guide"><span class="eyebrow">DAY ${s.day} · ${esc(E.mallOf(s).name)} · POP-UP PAVILION</span><h3>${esc(event.title)}</h3><p>${esc(event.description)}</p><p class="hint">An original, fictional game showcase of real catalog products. It is not a scheduled brand event. Browsing and comparing pause time, cost nothing and reserve no stock.</p><section class="pavilion-passport" role="status"><strong>${coupon.claimed?'Today’s stamp is in your passport.':'A new stamp for today’s visit.'}</strong><p>${coupon.active?`Your 10% game coupon is active for one ${esc(stockist.name)} checkout today.`:coupon.claimed?'No active coupon is saved. Your collected stamp remains in the passport.':`Collecting takes 10 game minutes and 2 stamina, adds 20 XP and gives a 10% game coupon for one ${esc(stockist.name)} checkout today.`}</p></section><div class="pavilion-comparison" id="pavilion-comparison" role="region" aria-label="Your exhibit comparison" tabindex="-1"><h4>${ids.length}/2 selected${ids.length===2?' · ready to compare':''}</h4>${selected.length?`<div class="pavilion-compare-grid">${selected.map(p=>`<article><strong>${esc(p.name)}</strong><p>${esc(E.categoryOf(p))} · ${p.sizes.map(esc).join(' / ')}</p><b>${E.money(E.price(s,p))} game price</b><p>${esc(p.material||'Read the linked source for the exact product specification.')}</p><button class="button secondary" data-action="pavilion-source" data-id="${esc(p.id)}">Read source notes</button></article>`).join('')}</div><p>Compare identity, format and game price. These different models are not a same-product price match or a physical-fit guarantee.</p><button class="text-button" data-action="pavilion-clear">Clear comparison</button>`:'<p>Choose up to two products below. You can change the pair without spending game money or time.</p>'}</div><div class="pavilion-products">${event.products.map(id=>{const p=E.byId(id),picked=ids.includes(id);return `<article class="product-card"><div class="product-art">${picture(p)}</div><div class="card-body"><small>${esc(p.brand)} · REAL PRODUCT REFERENCE</small><h4>${esc(p.name)}</h4><strong>${E.money(E.price(s,p))} game price</strong><p>${esc(E.categoryOf(p))} · ${p.sizes.map(esc).join(' / ')}</p><button class="button secondary pavilion-pick" data-action="pavilion-pick" data-id="${esc(id)}" aria-pressed="${picked}" ${!picked&&ids.length===2?'disabled':''}>${picked?'Selected ✓':'Add to comparison'}</button><button class="button secondary" data-action="pavilion-source" data-id="${esc(id)}">Source notes · free</button><button class="button secondary" data-action="demo" data-id="${esc(id)}">Try exhibit · 6 game min</button></div></article>`;}).join('')}</div><p>Purchases, stock and returns are handled at ${esc(stockist.name)}. A stamp is a once-per-game-day reward across all centers.</p><button class="button secondary wide" data-action="visit" data-id="${esc(stockist.id)}">Walk to ${esc(stockist.name)} ↗</button><button class="button secondary wide" data-action="close">Back to the pavilion</button></div>`;
}
export function pavilionFooterHTML(s,event,{E,esc}){const c=pavilionCoupon(s,event);return `<div class="pavilion-footer" role="group" aria-label="Today’s stamp"><div><strong>${c.claimed?'Stamp collected ✓':'Collect today’s stamp'}</strong><small>${c.active?`10% game coupon · ${esc(E.storeById(event.store).name)} · today`:c.claimed?'One stamp per day · all centers':'10 game min · 2 stamina · +20 XP'}</small></div><button class="button orange" data-action="popup-claim" ${c.claimed?'disabled':''}>${c.claimed?'Collected ✓':'Stamp & coupon'}</button></div>`;}
export function pavilionSourceHTML(s,event,id,{E,esc,picture}){if(!event.products.includes(id))return '';const p=E.byId(id);return `<div class="modal-body pavilion-source"><span class="eyebrow">SOURCE NOTES · FREE TO READ</span><h3>${esc(p.name)}</h3><div class="pavilion-source-photo product-art">${picture(p,{detail:true})}</div><p><strong>${esc(p.brand)}</strong> · ${esc(E.categoryOf(p))}</p><p>Selected formats: ${p.sizes.map(esc).join(' / ')}.</p><p>${esc(p.material||'Use the original source for exact specifications.')}</p><p>${E.money(E.price(s,p))} is a game price. ${esc(p.sourceOfferNote||p.priceBasis||'Actual prices and availability can change. This game does not establish real store inventory.')}</p><a class="source-link" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Original product reference ↗</a><p>No money, time, XP or stock is changed by reading these notes. Visit the stockist to make a game purchase.</p><button class="button secondary wide" data-action="pavilion-open">Back to today’s exhibit</button></div>`;}
